PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), school_name TEXT NOT NULL DEFAULT '', directorate TEXT NOT NULL DEFAULT '', wilaya TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', school_year TEXT NOT NULL DEFAULT '', semester TEXT NOT NULL DEFAULT 'الأول', subgroup_count INTEGER NOT NULL DEFAULT 4, print_orientation TEXT NOT NULL DEFAULT 'portrait', extra_json TEXT NOT NULL DEFAULT '{}');
INSERT OR IGNORE INTO settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS invigilation_rules (id INTEGER PRIMARY KEY CHECK(id=1), guards_per_room INTEGER DEFAULT 1, reserve_guards INTEGER DEFAULT 1, max_per_day INTEGER DEFAULT 2, avoid_consecutive_day INTEGER DEFAULT 0, require_consecutive_days INTEGER DEFAULT 0, balance TEXT DEFAULT 'equal', subject_teacher_rule TEXT DEFAULT 'must', subject_rule_explicit INTEGER DEFAULT 0, subject_reserve_count INTEGER DEFAULT 2, balance_extra_guards INTEGER DEFAULT 0, extra_json TEXT NOT NULL DEFAULT '{}');
INSERT OR IGNORE INTO invigilation_rules(id) VALUES(1);
CREATE TABLE IF NOT EXISTS groups (id TEXT PRIMARY KEY, level TEXT, branch TEXT, number TEXT);
CREATE TABLE IF NOT EXISTS students (id TEXT PRIMARY KEY, student_no TEXT, last_name TEXT, first_name TEXT, group_id TEXT, subgroup TEXT, birth_date TEXT DEFAULT '', gender TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS teachers (id TEXT PRIMARY KEY, last_name TEXT, first_name TEXT, subject_id TEXT);
CREATE TABLE IF NOT EXISTS subjects (id TEXT PRIMARY KEY, name TEXT);
CREATE TABLE IF NOT EXISTS rooms (id TEXT PRIMARY KEY, number TEXT, type TEXT, capacity INTEGER DEFAULT 0, note TEXT);
CREATE TABLE IF NOT EXISTS exam_sessions (id TEXT PRIMARY KEY, day TEXT, date TEXT, start TEXT, end TEXT);
CREATE TABLE IF NOT EXISTS exam_bookings (id TEXT PRIMARY KEY, session_id TEXT, subject_id TEXT, group_id TEXT, subject2_id TEXT);
CREATE TABLE IF NOT EXISTS assignments (id TEXT PRIMARY KEY, group_id TEXT, room_id TEXT, sub TEXT, count INTEGER DEFAULT 0, manual INTEGER DEFAULT 0, merged INTEGER DEFAULT 0, gender TEXT DEFAULT '', shared INTEGER DEFAULT 0, shared_same_time INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS assignment_students (assignment_id TEXT, student_id TEXT, PRIMARY KEY(assignment_id,student_id));
CREATE TABLE IF NOT EXISTS assignment_groups (assignment_id TEXT, group_id TEXT, PRIMARY KEY(assignment_id,group_id));
CREATE TABLE IF NOT EXISTS absences (id TEXT PRIMARY KEY, date TEXT, time TEXT, subject_id TEXT, group_id TEXT, student_id TEXT, session_id TEXT, justified TEXT, reason TEXT);
CREATE TABLE IF NOT EXISTS invigilations (id TEXT PRIMARY KEY, date TEXT, period TEXT, time TEXT, teacher_id TEXT, room_id TEXT, session_id TEXT, status TEXT, justified TEXT, note TEXT, seat TEXT, mandatory INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS teacher_guard_absences (id TEXT PRIMARY KEY, session_id TEXT, date TEXT, period TEXT, time TEXT, teacher_id TEXT, justified TEXT, note TEXT);
CREATE TABLE IF NOT EXISTS double_room_rules (id TEXT PRIMARY KEY, session_id TEXT, count INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS double_room_rule_rooms (rule_id TEXT, room_id TEXT, PRIMARY KEY(rule_id,room_id));
CREATE TABLE IF NOT EXISTS exclusion_rules (id TEXT PRIMARY KEY, teacher_id TEXT, date TEXT, start TEXT, end TEXT);
CREATE TABLE IF NOT EXISTS app_user (id INTEGER PRIMARY KEY CHECK(id=1), username TEXT NOT NULL DEFAULT 'admin', password_hash TEXT NOT NULL DEFAULT '', password_salt TEXT NOT NULL DEFAULT '', recovery_hash TEXT NOT NULL DEFAULT '', recovery_salt TEXT NOT NULL DEFAULT '');
INSERT OR IGNORE INTO app_user(id) VALUES(1);
CREATE TABLE IF NOT EXISTS license (id INTEGER PRIMARY KEY CHECK(id=1), device_id TEXT NOT NULL DEFAULT '', code TEXT NOT NULL DEFAULT '', last_seen INTEGER NOT NULL DEFAULT 0, activated INTEGER NOT NULL DEFAULT 0, activation_code TEXT NOT NULL DEFAULT '', activated_at TEXT);
INSERT OR IGNORE INTO license(id) VALUES(1);
-- بيانات الواجهة التي ليس لها جدول مستقل (الحجوزات المؤقتة، المواد المسبقة، وثائق الاستلام، سجلات المراقبة...) تُحفظ كما هي بصيغة JSON
CREATE TABLE IF NOT EXISTS app_extras (id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL DEFAULT '{}');
INSERT OR IGNORE INTO app_extras(id) VALUES(1);
-- موافقة المستخدم على شروط الاستخدام والخصوصية والأمان (تُعرض بعد تسجيل الدخول)
CREATE TABLE IF NOT EXISTS terms_acceptance (id INTEGER PRIMARY KEY CHECK(id=1), version TEXT NOT NULL DEFAULT '', accepted_at TEXT, username TEXT NOT NULL DEFAULT '', device_id TEXT NOT NULL DEFAULT '');
INSERT OR IGNORE INTO terms_acceptance(id) VALUES(1);
